with c as (select id, content, position($x$<h3>Mad C101 | Carolina Herrera 212 Men Muadili</h3>$x$ in content) s from blog_posts where slug='mad-parfum-muadil-listesi'),
c2 as (select id, content, s, s + 4 + position('<h3>' in substring(content from s+4)) - 1 e from c)
update blog_posts b set content = substring(c2.content from 1 for c2.s-1) || (select replace(replace(replace(replace(substring(content from s for e-s), $x$<p><a target="_self" class="text-blue-600 underline decoration-blue-300 font-medium" href="https://uygunbakim.com/product/mad-parfum-b107-selective-kadin"><strong><u>Mad B107</u></strong></a>, lavanta ve bergamotun yarattığı o tertemiz, asil açılışla teninizde ferah bir başlangıç yapıyor. Ancak bu klasik yapının asıl heyecan verici yanı, orta notalarda beyaz çiçeklerin arasına sızan çikolata dokunuşu; bu beklenmedik gurme detay, kokuyu sıradan bir çiçeksi parfümden çıkarıp modern ve iştah açıcı bir derinliğe taşıyor.</p>$x$, ''), $x$<p>Kuruma aşamasında ise vanilya ve sandal ağacının kremsi sıcaklığı, çikolatanın tatlılığını mühürleyerek tende kalıcı ve güven veren bir imza bırakıyor. <a target="_self" class="text-blue-600 underline decoration-blue-300 font-medium" href="https://uygunbakim.com/product/guerlain-mon-guerlain-l-essence"><strong><u>Guerlain Mon Guerlain L'Essence</u></strong></a> karakterini %77 nota benzerliğiyle yakalayan B107, hem geleneksel bir zarafeti hem de çağdaş bir tatlılığı aynı anda taşımak isteyenler için koleksiyonun en özgün dengelerinden birini sunuyor.</p>$x$, ''), $x$<p>B107 aynı zamanda <a target="_self" class="text-blue-600 underline decoration-blue-300 font-medium" href="https://uygunbakim.com/product/nishane-santalove"><strong><u>Nishane Santalove</u></strong></a> ile de notalarıyl %65 benzerlik göstermekte.</p>$x$, ''), $x$<div data-id="24532" data-type="muadil-card"></div>$x$, $x$<div data-id="24532" data-type="muadil-card"></div><p><a target="_self" class="text-blue-600 underline decoration-blue-300 font-medium" href="https://uygunbakim.com/product/mad-parfum-c101-selective"><strong><u>Mad C101</u></strong></a>, <a target="_self" class="text-blue-600 underline decoration-blue-300 font-medium" href="https://uygunbakim.com/product/carolina-herrera-212-men"><strong><u>Carolina Herrera 212 Men</u></strong></a>'in muadilidir (%64 nota benzerliği). Zencefil, gardenya ve adaçayından oluşan kalp ile misk, sandal ağacı ve vetiverli dip iki parfümde de ortak. Fark: 212 Men greyfurt, bergamot, lavanta ve petitgrainle açılır; C101'de ise bunların yerine yeşil biber, menekşe ve guayak ağacı bulunur.</p>$x$) from c2 x where x.id=c2.id) || substring(c2.content from c2.e), updated_at = now()
from c2 where b.id = c2.id and c2.s > 0 and position($x$<p><a target="_self" class="text-blue-600 underline decoration-blue-300 font-medium" href="https://uygunbakim.com/product/mad-parfum-b107-selective-kadin"><strong><u>Mad B107</u></strong></a>, lavanta ve bergamotun yarattığı o tertemiz, asil açılışla teninizde ferah bir başlangıç yapıyor. Ancak bu klasik yapının asıl heyecan verici yanı, orta notalarda beyaz çiçeklerin arasına sızan çikolata dokunuşu; bu beklenmedik gurme detay, kokuyu sıradan bir çiçeksi parfümden çıkarıp modern ve iştah açıcı bir derinliğe taşıyor.</p>$x$ in substring(c2.content from c2.s for c2.e-c2.s))>0 and position($x$<p>Kuruma aşamasında ise vanilya ve sandal ağacının kremsi sıcaklığı, çikolatanın tatlılığını mühürleyerek tende kalıcı ve güven veren bir imza bırakıyor. <a target="_self" class="text-blue-600 underline decoration-blue-300 font-medium" href="https://uygunbakim.com/product/guerlain-mon-guerlain-l-essence"><strong><u>Guerlain Mon Guerlain L'Essence</u></strong></a> karakterini %77 nota benzerliğiyle yakalayan B107, hem geleneksel bir zarafeti hem de çağdaş bir tatlılığı aynı anda taşımak isteyenler için koleksiyonun en özgün dengelerinden birini sunuyor.</p>$x$ in substring(c2.content from c2.s for c2.e-c2.s))>0 and position($x$<p>B107 aynı zamanda <a target="_self" class="text-blue-600 underline decoration-blue-300 font-medium" href="https://uygunbakim.com/product/nishane-santalove"><strong><u>Nishane Santalove</u></strong></a> ile de notalarıyl %65 benzerlik göstermekte.</p>$x$ in substring(c2.content from c2.s for c2.e-c2.s))>0
returning b.id, length(b.content);